-- Disposable fixture only. Rollback preserves even the isolated database.
begin;
select extensions.plan(1);
do $$
declare
 owner_id uuid:=gen_random_uuid(); doctor_id uuid:=gen_random_uuid(); reception_id uuid:=gen_random_uuid(); foreign_owner uuid:=gen_random_uuid();
 biz uuid; foreign_biz uuid; prof uuid; second_prof uuid; foreign_prof uuid; svc uuid; integration uuid; integration_revision bigint; availability_revision bigint;
 s jsonb; merged jsonb; payload jsonb; original jsonb; info jsonb; changed jsonb; response uuid; replay_response uuid; created record; replay record; previous_patients integer; previous_appointments integer;
 at_time timestamptz:=date_trunc('day',now())+interval '20 days 10 hours'; request_key uuid:=gen_random_uuid(); next_key uuid:=gen_random_uuid();
 fields jsonb:='[{"id":"insurance","label":"Obra social","kind":"text","required":true,"maxLength":120,"patientField":"insurance"},{"id":"age","label":"Edad","kind":"text","required":true,"maxLength":3,"patientField":"age"},{"id":"medication","label":"Medicación","kind":"textarea","required":false,"maxLength":1000,"patientField":"medication"},{"id":"allergies","label":"Alergias","kind":"textarea","required":false,"maxLength":1000,"patientField":"allergies"},{"id":"other","label":"Otro dato","kind":"boolean","required":false,"patientField":"custom"}]';
 answers jsonb:='{"profile_insurance":"Particular","profile_age":"35","profile_medication":"Declaración sintética","profile_allergies":"Sin alergias conocidas"}';
begin
 insert into auth.users(id,email) values(owner_id,'info-owner@example.test'),(doctor_id,'info-doctor@example.test'),(reception_id,'info-reception@example.test'),(foreign_owner,'info-other@example.test');
 insert into public.businesses(name,slug,industry,timezone) values('Consultorio datos ficticios','info-'||gen_random_uuid(),'other','UTC') returning id into biz;
 insert into public.businesses(name,slug,industry,timezone) values('Consultorio ajeno','foreign-info-'||gen_random_uuid(),'other','UTC') returning id into foreign_biz;
 insert into public.business_users(business_id,user_id,role,status,accepted_at) values(biz,owner_id,'owner','active',now()),(biz,doctor_id,'professional','active',now()),(biz,reception_id,'reception','active',now()),(foreign_biz,foreign_owner,'owner','active',now());
 update public.business_subscriptions set commercial_access_enabled=true,is_permanent=true,subscription_status='active',paid_until=null,grace_until=null,restricted_until=null where business_id in (biz,foreign_biz);
 insert into public.professionals(business_id,name) values(biz,'Profesional A') returning id into prof;
 insert into public.professionals(business_id,name) values(biz,'Profesional B') returning id into second_prof;
 insert into public.professionals(business_id,name) values(foreign_biz,'Profesional externa') returning id into foreign_prof;
 insert into public.professional_users(business_id,professional_id,user_id) values(biz,prof,doctor_id);
 insert into public.services(business_id,name,duration_minutes) values(biz,'Consulta ficticia',30) returning id into svc;
 insert into public.professional_services(business_id,professional_id,service_id) values(biz,prof,svc),(biz,second_prof,svc);
 perform set_config('request.jwt.claim.sub',owner_id::text,true); perform set_config('request.jwt.claim.role','authenticated',true);
 if public.save_professional_booking_form(biz,prof,0,fields)<>1 then raise exception 'FAIL_CREATE_FORM'; end if;
 begin perform public.save_professional_booking_form(biz,prof,0,fields); raise exception 'FAIL_STALE_FORM'; exception when others then if sqlerrm<>'BOOKING_INTEGRATION_CHANGED' then raise; end if; end;
 begin perform public.save_professional_booking_form(biz,prof,1,fields||jsonb_build_array(fields->0)); raise exception 'FAIL_DUPLICATE_MAPPING'; exception when others then if sqlerrm<>'BOOKING_INTAKE_SCHEMA_INVALID' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',doctor_id::text,true);
 if public.save_professional_booking_form(biz,prof,1,fields)<>2 then raise exception 'FAIL_DOCTOR_OWN_FORM'; end if;
 begin perform public.save_professional_booking_form(biz,second_prof,0,fields); raise exception 'FAIL_DOCTOR_OTHER_FORM'; exception when others then if sqlerrm<>'BOOKING_CONFIG_ACCESS_DENIED' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',reception_id::text,true);
 begin perform public.save_professional_booking_form(biz,prof,2,fields); raise exception 'FAIL_RECEPTION_FORM_WRITE'; exception when others then if sqlerrm<>'BOOKING_CONFIG_ACCESS_DENIED' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',foreign_owner::text,true);
 begin perform public.save_professional_booking_form(biz,prof,2,fields); raise exception 'FAIL_FOREIGN_FORM_WRITE'; exception when others then if sqlerrm<>'BOOKING_CONFIG_ACCESS_DENIED' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.save_professional_booking_form(biz,second_prof,0,'[{"id":"insurance","label":"Cobertura","kind":"text","required":false,"maxLength":50,"patientField":"insurance"}]');
 merged:=public.get_public_patient_booking_schema(biz,array[prof,second_prof]);
 if jsonb_array_length(merged->'schema')<>5 or not exists(select 1 from jsonb_array_elements(merged->'schema') f where f->>'id'='profile_insurance' and f->>'required'='true' and f->>'maxLength'='50') then raise exception 'FAIL_JOINT_SCHEMA_MERGE'; end if;
 s:=public.get_public_patient_booking_schema(biz,array[prof]);
 answers:=answers||jsonb_build_object('prof_'||md5(prof::text||':other'),false);
 payload:=jsonb_build_object('business_id',biz,'professional_ids',array[prof],'patient_name','Paciente Sintética','patient_phone_raw','3425048209','patient_phone_e164','+5493425048209','service_id',svc,'starts_at',at_time,'request_key',request_key,'schema_hash',s->>'hash','answers',answers,'comment','Comentario privado','phone_status','valid');
 select count(*) into previous_patients from public.patients where business_id=biz; select count(*) into previous_appointments from public.appointments where business_id=biz;
 begin perform * from public.create_public_booking_with_information(payload||jsonb_build_object('answers',answers-'profile_insurance')); raise exception 'FAIL_REQUIRED_BYPASS'; exception when others then if sqlerrm<>'BOOKING_INTAKE_REQUIRED' then raise; end if; end;
 begin perform * from public.create_public_booking_with_information(payload||jsonb_build_object('answers',answers||'{"profile_age":"999"}')); raise exception 'FAIL_INVALID_AGE'; exception when others then if sqlerrm<>'BOOKING_PROFILE_DATA_INVALID' then raise; end if; end;
 begin perform * from public.create_public_booking_with_information(payload||jsonb_build_object('schema_hash','bad')); raise exception 'FAIL_STALE_SCHEMA'; exception when others then if sqlerrm<>'BOOKING_INFORMATION_CHANGED' then raise; end if; end;
 if (select count(*) from public.patients where business_id=biz)<>previous_patients or (select count(*) from public.appointments where business_id=biz)<>previous_appointments then raise exception 'FAIL_FAILED_BOOKING_NOT_ATOMIC'; end if;
 select * into created from public.create_public_booking_with_information(payload);
 if not exists(select 1 from public.patients where id=created.patient_id and insurance='Particular') or not exists(select 1 from public.patient_clinical_profiles where patient_id=created.patient_id and medication='Declaración sintética' and allergies='Sin alergias conocidas' and custom_fields->'booking_age'->>'years'='35' and updated_by is null) then raise exception 'FAIL_PROFILE_NOT_UPDATED'; end if;
 if (select internal_note from public.appointments where id=created.id) is not null then raise exception 'FAIL_PRIVATE_COMMENT_IN_OPERATIONAL_NOTE'; end if;
 if not exists(select 1 from public.patient_clinical_profiles where patient_id=created.patient_id and custom_fields->'booking_fields'->('prof_'||md5(prof::text||':other'))->'value'='false'::jsonb and custom_fields->>'booking_last_reported_at' is not null) then raise exception 'FAIL_CUSTOM_FALSE_OR_PROVENANCE'; end if;
 if not exists(select 1 from public.appointment_intake_submissions where appointment_id=created.id and profile_changes->>'source'='patient_booking' and profile_changes->'after'->>'insurance'='Particular') then raise exception 'FAIL_PROFILE_PROVENANCE'; end if;
 original:=s; select * into replay from public.create_public_booking_with_information(payload,true);
 if replay.id<>created.id or not replay.idempotent_replay or (select count(*) from public.appointment_intake_submissions where appointment_id=created.id)<>1 then raise exception 'FAIL_BOOKING_REPLAY_DUPLICATED'; end if;
 begin perform * from public.create_public_booking_with_information(payload||jsonb_build_object('answers',answers||'{"profile_insurance":"Otra cobertura"}'),true); raise exception 'FAIL_REPLAY_CHANGED_DATA'; exception when others then if sqlerrm<>'APPOINTMENT_IDEMPOTENCY_CONFLICT' then raise; end if; end;
 update public.patient_clinical_profiles set background='Antecedentes conservados',custom_fields=custom_fields||'{"unrelated":"Preservar"}' where patient_id=created.patient_id;
 info:=public.get_public_booking_information(created.confirmation_token);
 if info->>'theme'<>'cita-suite' then raise exception 'FAIL_NATIVE_INFORMATION_THEME'; end if;
 if info::text like '%Antecedentes conservados%' or info::text like '%Preservar%' then raise exception 'FAIL_PUBLIC_PROFILE_READBACK'; end if;
 response:=public.submit_public_booking_information(created.confirmation_token,next_key,info->>'schema_hash',info->>'version',answers-'profile_medication'-'profile_allergies','Segundo comentario');
 replay_response:=public.submit_public_booking_information(created.confirmation_token,next_key,info->>'schema_hash',info->>'version',answers-'profile_medication'-'profile_allergies','Segundo comentario');
 if response<>replay_response or (select count(*) from public.appointment_intake_submissions where appointment_id=created.id)<>2 then raise exception 'FAIL_INFORMATION_REPLAY_DUPLICATED'; end if;
 if not exists(select 1 from public.patient_clinical_profiles where patient_id=created.patient_id and background='Antecedentes conservados' and medication='Declaración sintética' and allergies='Sin alergias conocidas' and custom_fields->>'unrelated'='Preservar') then raise exception 'FAIL_OMITTED_ANSWERS_CLEARED_PROFILE'; end if;
 begin perform public.submit_public_booking_information(created.confirmation_token,gen_random_uuid(),info->>'schema_hash',info->>'version',answers,null); raise exception 'FAIL_STALE_INFORMATION_VERSION'; exception when others then if sqlerrm<>'BOOKING_INFORMATION_CHANGED' then raise; end if; end;
 perform public.save_professional_booking_form(biz,prof,2,'[]');
 s:=public.get_public_patient_booking_schema(biz,array[prof],null,request_key::text);
 if s<>original then raise exception 'FAIL_RETRY_SCHEMA_CHANGED'; end if;
 select * into replay from public.create_public_booking_with_information(payload,true);
 if replay.id<>created.id then raise exception 'FAIL_FORM_CHANGED_BROKE_RETRY'; end if;
 -- Embedding uses the same mapped form and preserves committed retries after link changes.
 perform public.save_professional_booking_form(biz,prof,3,fields);
 insert into public.booking_integrations(business_id,name,is_active,theme,allowed_origins,allowed_service_ids,allowed_professional_ids,intake_schema) values(biz,'Ficticia',true,'natalia',array['https://example.test'],array[svc],array[prof],'[{"id":"legacy","label":"Pregunta del enlace","kind":"text","required":true,"maxLength":120}]') returning id,revision into integration,integration_revision;
 select booking_availability_revision into availability_revision from public.businesses where id=biz;
 s:=public.get_public_patient_booking_schema(biz,array[prof],integration);
 payload:=payload||jsonb_build_object('request_key',gen_random_uuid(),'starts_at',at_time+interval '2 hours','schema_hash',s->>'hash','integration_id',integration,'integration_revision',integration_revision,'availability_revision',availability_revision,'modality','in_person','entry_point','embedded','answers',answers||'{"legacy":"Respuesta original"}');
 select * into replay from public.create_public_booking_with_information(payload);
 if public.get_public_booking_catalogue(integration)->'services'->0->>'name'<>'Consulta ficticia' or public.get_public_booking_catalogue(integration)::text like '%Paciente Sintética%' then raise exception 'FAIL_CATALOGUE_SCOPE_OR_PRIVACY'; end if;
 update public.booking_integrations set intake_schema='[]',is_active=false,theme='cita-suite' where id=integration;
 select * into created from public.create_public_booking_with_information(payload,true);
 if public.get_public_booking_information(created.confirmation_token)->>'theme'<>'natalia' then raise exception 'FAIL_HISTORICAL_INFORMATION_THEME'; end if;
 if created.id<>replay.id or not created.idempotent_replay then raise exception 'FAIL_EMBEDDED_RETRY_BROKEN'; end if;
 -- Birth dates are validated before commit, including impossible and future dates.
 perform public.save_professional_booking_form(biz,second_prof,1,'[{"id":"birth","label":"Fecha de nacimiento","kind":"text","required":true,"maxLength":10,"patientField":"birth_date"}]');
 s:=public.get_public_patient_booking_schema(biz,array[second_prof]);
 payload:=jsonb_build_object('business_id',biz,'professional_ids',array[second_prof],'patient_name','Paciente Fecha','patient_phone_raw','3425048210','patient_phone_e164','+5493425048210','service_id',svc,'starts_at',at_time,'request_key',gen_random_uuid(),'schema_hash',s->>'hash','answers',jsonb_build_object('profile_birth_date','2026-02-30'),'phone_status','valid');
 select count(*) into previous_patients from public.patients where business_id=biz;
 begin perform * from public.create_public_booking_with_information(payload); raise exception 'FAIL_IMPOSSIBLE_BIRTH_DATE'; exception when others then if sqlerrm<>'BOOKING_PROFILE_DATA_INVALID' then raise; end if; end;
 begin perform * from public.create_public_booking_with_information(payload||jsonb_build_object('answers',jsonb_build_object('profile_birth_date',(current_date+1)::text))); raise exception 'FAIL_FUTURE_BIRTH_DATE'; exception when others then if sqlerrm<>'BOOKING_PROFILE_DATA_INVALID' then raise; end if; end;
 if (select count(*) from public.patients where business_id=biz)<>previous_patients then raise exception 'FAIL_BIRTH_DATE_ROLLBACK'; end if;
 select * into replay from public.create_public_booking_with_information(payload||jsonb_build_object('answers',jsonb_build_object('profile_birth_date','1990-05-12')));
 if not exists(select 1 from public.patients where id=replay.patient_id and birth_date='1990-05-12') then raise exception 'FAIL_BIRTH_DATE_NOT_STORED'; end if;
 -- Conflicting professional choices fail instead of weakening a required answer.
 perform public.save_professional_booking_form(biz,second_prof,2,'[{"id":"coverage","label":"Cobertura","kind":"choice","required":true,"options":["Otra"],"patientField":"insurance"}]');
 begin perform public.get_public_patient_booking_schema(biz,array[prof,second_prof]); raise exception 'FAIL_INCOMPATIBLE_JOINT_FIELDS'; exception when others then if sqlerrm<>'BOOKING_PROFILE_OPTIONS_CONFLICT' then raise; end if; end;
 -- Public and reception roles cannot read clinical declarations; foreign owners see none.
 perform set_config('request.jwt.claim.sub',reception_id::text,true); execute 'set local role authenticated';
 if exists(select 1 from public.appointment_intake_submissions where business_id=biz) then raise exception 'FAIL_RECEPTION_READS_CLINICAL'; end if;
 execute 'reset role'; perform set_config('request.jwt.claim.sub',foreign_owner::text,true); execute 'set local role authenticated';
 if exists(select 1 from public.appointment_intake_submissions where business_id=biz) then raise exception 'FAIL_FOREIGN_READS_CLINICAL'; end if;
 execute 'reset role';
 if has_function_privilege('anon','public.get_public_booking_catalogue(uuid)','execute') or has_function_privilege('anon','public.create_public_booking_with_information(jsonb,boolean)','execute') or has_function_privilege('authenticated','public.get_public_booking_information(text)','execute') or has_table_privilege('authenticated','public.appointment_intake_submissions','insert') or has_table_privilege('anon','public.professional_booking_forms','select') then raise exception 'FAIL_UNSAFE_GRANT'; end if;
 -- A patient reassignment invalidates the original link rather than revealing another profile.
 insert into public.patients(business_id,full_name) values(biz,'Otra paciente') returning id into response;
 begin update public.appointments set patient_id=response where id=created.id; raise exception 'FAIL_APPOINTMENT_PATIENT_MUTABLE'; exception when others then if sqlerrm<>'APPOINTMENT_IDENTITY_FIELDS_IMMUTABLE' then raise; end if; end;
 update public.patients set archived_at=now() where id=created.patient_id;
 begin perform public.get_public_booking_information(created.confirmation_token); raise exception 'FAIL_REASSIGNED_LINK'; exception when others then if sqlerrm<>'BOOKING_INFORMATION_UNAVAILABLE' then raise; end if; end;
end $$;
select extensions.pass('Required fields, profile persistence, history, retries, form authorization and clinical isolation');
select * from extensions.finish();
rollback;
